// Get current time in local timezone (Asia/Calcutta)
const now = new Date();
const currentTime = now.toLocaleTimeString('en-US', { 
  timeZone: 'Asia/Kolkata',
  hour: '2-digit', 
  minute: '2-digit',
  hour12: false 
});

const matchingItems = [];
const seenUsers = new Set();

for (const item of $input.all()) {
  // Get medicine time and normalize it
  let medicineTime = item.json.Time;
  const chatId = item.json['Telegram Chat ID'];

  // Skip if we already processed this user in this run
  if (seenUsers.has(chatId)) {
    continue;
  }

  // Handle different time formats
  if (medicineTime) {
    medicineTime = medicineTime.toString().trim();

    // If time is in format "8:00" convert to "08:00"
    const timeParts = medicineTime.split(':');
    if (timeParts.length === 2) {
      const hours = timeParts[0].padStart(2, '0');
      const minutes = timeParts[1].padStart(2, '0');
      medicineTime = hours + ':' + minutes;
    }

    // Compare times
    if (currentTime === medicineTime) {
      matchingItems.push({
        json: {
          ...item.json,
          timeMatch: true,
          currentTime: currentTime,
          medicineTime: medicineTime
        }
      });
      seenUsers.add(chatId);
    }
  }
}

return matchingItems;

const items = $input.all();
const userGroups = {};

// Group by user (Telegram Chat ID)
items.forEach(item => {
  const chatId = item.json['Telegram Chat ID'];
  const name = item.json.Name;
  const status = item.json.Status;

  if (!userGroups[chatId]) {
    userGroups[chatId] = {
      name: name,
      chatId: chatId,
      total: 0,
      taken: 0
    };
  }

  userGroups[chatId].total++;
  if (status === 'Taken') {
    userGroups[chatId].taken++;
  }
});

// Convert to array
return Object.values(userGroups).map(user => ({
  name: user.name,
  chatId: user.chatId,
  taken: user.taken,
  total: user.total,
  message: `📊 Daily Summary for ${user.name}:\n\nYou took ${user.taken}/${user.total} medicines today.\n\n${user.taken === user.total ? '🎉 Perfect! Keep it up!' : '💪 Tomorrow is a new day - you can do it!'}`
}));
